function shuffleQuestionOptions(q: any) {
  const originalOpts = [...q.options];
  const correctText = originalOpts[q.correctOptionIndex];

  const shuffledOpts = [...originalOpts];
  for (let i = shuffledOpts.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffledOpts[i], shuffledOpts[j]] = [shuffledOpts[j], shuffledOpts[i]];
  }

  const newIdx = shuffledOpts.indexOf(correctText);
  return {
    ...q,
    options: shuffledOpts,
    correctOptionIndex: newIdx >= 0 ? newIdx : q.correctOptionIndex,
  };
}

async function seedSkillTests() {
  try {
    await mongoose.connect(MONGO_URI);
    console.log('Connected to MongoDB Atlas for Skill Tests Seeding...');

    for (const testData of testsToSeed) {
      const processedQuestions = testData.questions.map(shuffleQuestionOptions);
      const computedTimeMinutes = Math.ceil((processedQuestions.length * 20) / 60);

      const payload = {
        ...testData,
        timeLimitMinutes: computedTimeMinutes,
        questions: processedQuestions,
      };

      await SkillTest.findOneAndUpdate(
        { skillName: testData.skillName },
        payload,
        { upsert: true, new: true }
      );
      console.log(`Seeded Skill Test: "${testData.title}" (${testData.skillName}) - ${processedQuestions.length} questions (${computedTimeMinutes} Mins)`);
    }

    console.log('✅ All 11 Skill Tests seeded with option shuffling and dynamic time limits!');
    process.exit(0);
  } catch (err) {
    console.error('❌ Skill Test Seeding Error:', err);
    process.exit(1);
  }
}

seedSkillTests();
